### Task 7: A press is forwarded, and answered

**Files:**
- Modify: `hosted/infra/lib/handlers/ws.ts`
- Test: `hosted/infra/test/ws.test.ts`

**Interfaces:**
- Consumes: `writes()` from Task 3, `Attached.deck` from Task 1.
- Produces: wire messages `{ t: "drive", from, run, seq, ref, press, move?, answer? }` (server → page), `{ t: "drove", to, ref, ok, say? }` (page → server), `{ t: "drove", ref, ok, say? }` (server → deck).

- [ ] **Step 1: Write the failing test**

```ts
it("forwards a press to the page and the verdict back to the deck", async () => {
  const live = memoryLive();
  const posted: Array<[string, string]> = [];
  const poster: Poster = { post: async (id, data) => (posted.push([id, data]), "ok") };
  const deps = depsWith({ live, poster });
  await route({ requestContext: { routeKey: "$connect", connectionId: "deck1" }, queryStringParameters: { token: "good", as: "deck" } }, deps);
  await route({ requestContext: { routeKey: "$connect", connectionId: "page" }, queryStringParameters: { token: "good" } }, deps);
  await route({ requestContext: { routeKey: "$default", connectionId: "page" }, body: JSON.stringify({ t: "watch", id: "s1" }) }, deps);
  posted.length = 0;

  await route(
    {
      requestContext: { routeKey: "$default", connectionId: "deck1" },
      body: JSON.stringify({ t: "drive", run: "s1", seq: 42, ref: "r1", press: "primary" }),
    },
    deps,
  );
  expect(JSON.parse(posted.find(([id]) => id === "page")![1])).toEqual({
    t: "drive", from: "deck1", run: "s1", seq: 42, ref: "r1", press: "primary",
  });

  posted.length = 0;
  await route(
    { requestContext: { routeKey: "$default", connectionId: "page" }, body: JSON.stringify({ t: "drove", to: "deck1", ref: "r1", ok: true }) },
    deps,
  );
  expect(JSON.parse(posted.find(([id]) => id === "deck1")![1])).toEqual({ t: "drove", ref: "r1", ok: true });
});

it("tells a deck when nothing is holding the run", async () => {
  const live = memoryLive();
  const posted: Array<[string, string]> = [];
  const poster: Poster = { post: async (id, data) => (posted.push([id, data]), "ok") };
  const deps = depsWith({ live, poster });
  await route({ requestContext: { routeKey: "$connect", connectionId: "deck1" }, queryStringParameters: { token: "good", as: "deck" } }, deps);
  posted.length = 0;
  await route(
    { requestContext: { routeKey: "$default", connectionId: "deck1" }, body: JSON.stringify({ t: "drive", run: "s1", seq: 1, ref: "r2", press: "primary" }) },
    deps,
  );
  expect(JSON.parse(posted.at(-1)![1])).toEqual({ t: "drove", ref: "r2", ok: false, say: "Nothing is holding that run." });
});

it("will not forward a press for somebody else's run", async () => {
  const live = memoryLive();
  const posted: Array<[string, string]> = [];
  const poster: Poster = { post: async (id, data) => (posted.push([id, data]), "ok") };
  const deps = depsWith({ live, poster, ownerOf: { s1: "user_b" } });
  await route({ requestContext: { routeKey: "$connect", connectionId: "deck1" }, queryStringParameters: { token: "good", as: "deck" } }, deps);
  posted.length = 0;
  await route(
    { requestContext: { routeKey: "$default", connectionId: "deck1" }, body: JSON.stringify({ t: "drive", run: "s1", seq: 1, ref: "r3", press: "primary" }) },
    deps,
  );
  expect(JSON.parse(posted.at(-1)![1])).toMatchObject({ ok: false });
});
```

- [ ] **Step 2: Run test to verify it fails**

Run: `npm test -w hosted/infra -- ws`
Expected: FAIL with `unknown message`.

- [ ] **Step 3: Handle the press**

In `ws.ts`, after the `event` branch and before the public/stream early return:

```ts
/**
 * A deck pressing something.
 *
 * The server checks who is asking and finds the devices that could take
 * it; it does not read the press. What may be pressed is the run's
 * business, and the run is the only thing holding the pack and the log.
 *
 * Nothing is stored. A press is worth exactly as much as the moment it
 * was made in: `seq` names the offer it was drawn from, and the writing
 * device refuses one it has already moved past. Durability would buy a
 * press that lands after the reason for it has gone.
 */
if (conn.deck && m["t"] === "drive") {
  const poster = deps.poster;
  const ref = typeof m["ref"] === "string" ? m["ref"].slice(0, 64) : "";
  const run = typeof m["run"] === "string" ? m["run"] : "";
  const refuse = async (say: string): Promise<WsResult> => {
    if (poster) {
      try {
        await poster.post(connectionId, JSON.stringify({ t: "drove", ref, ok: false, say }));
      } catch (error) {
        console.error("live: could not refuse a press", error);
      }
    }
    return { statusCode: 200 };
  };
  if (!ref || !run) return { statusCode: 400, body: "a press has a run and a ref" };
  const session = await deps.store.getSession(run);
  if (!session || session.meta.deletedAt || session.meta.ownerSub !== conn.sub) return refuse("That run is not yours to press.");
  if (session.meta.endedAt) return refuse("That run has ended.");

  const writers = (await deps.live.watchers(run)).filter(writes);
  if (writers.length === 0) return refuse("Nothing is holding that run.");
  if (!poster) return { statusCode: 200 };

  const line = JSON.stringify({
    t: "drive",
    from: connectionId,
    run,
    seq: typeof m["seq"] === "number" ? m["seq"] : 0,
    ref,
    press: String(m["press"] ?? ""),
    ...(typeof m["move"] === "string" ? { move: m["move"] } : {}),
    ...(m["answer"] && typeof m["answer"] === "object" ? { answer: m["answer"] } : {}),
  });
  for (const w of writers) {
    try {
      if ((await poster.post(w.connectionId, line)) === "gone") await deps.live.disconnect(w.connectionId);
    } catch (error) {
      console.error("live: could not pass a press on", error);
    }
  }
  return { statusCode: 200 };
}

/**
 * The verdict, on its way back to the one deck that asked.
 *
 * The deck's connection id came out with the press and goes back with
 * the answer, so the server keeps no record of who asked for what. It is
 * checked before it is posted to: a member may only answer a deck of
 * their own account.
 */
if (m["t"] === "drove" && typeof m["to"] === "string") {
  const poster = deps.poster;
  if (!poster) return { statusCode: 200 };
  const target = await deps.live.connection(m["to"]);
  if (!target || !target.deck || target.sub !== conn.sub) return { statusCode: 200 };
  const line = JSON.stringify({
    t: "drove",
    ref: typeof m["ref"] === "string" ? m["ref"] : "",
    ok: m["ok"] === true,
    ...(typeof m["say"] === "string" ? { say: m["say"] } : {}),
  });
  try {
    if ((await poster.post(m["to"], line)) === "gone") await deps.live.disconnect(m["to"]);
  } catch (error) {
    console.error("live: could not pass a verdict back", error);
  }
  return { statusCode: 200 };
}
```

- [ ] **Step 4: Run the tests**

Run: `npm test -w hosted/infra -- ws`
Expected: PASS, three new tests.

- [ ] **Step 5: Commit**

```bash
npm run typecheck
git add hosted/infra/lib/handlers/ws.ts hosted/infra/test/ws.test.ts
git commit -m "feat(live): a deck's press reaches the device holding the run"
```

